const lockClass = `-- name: LockClass :one
SELECT id, org_id, academic_year_id, name, created_by, created_at, archived_at FROM classes WHERE org_id = $1 AND id = $2 AND archived_at IS NULL FOR UPDATE
`

type LockClassParams struct {
	OrgID uuid.UUID
	ID    uuid.UUID
}

func (q *Queries) LockClass(ctx context.Context, arg LockClassParams) (Class, error) {
	row := q.db.QueryRow(ctx, lockClass, arg.OrgID, arg.ID)
	var i Class
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.AcademicYearID,
		&i.Name,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.ArchivedAt,
	)
	return i, err
}

const lockOrgYears = `-- name: LockOrgYears :exec
SELECT pg_advisory_xact_lock(hashtextextended('academic_years:' || $1::uuid::text, 0))
`

// Serializes year creation/activation per school (first year becomes active exactly once).
func (q *Queries) LockOrgYears(ctx context.Context, orgID uuid.UUID) error {
	_, err := q.db.Exec(ctx, lockOrgYears, orgID)
	return err
}

const renameClass = `-- name: RenameClass :one
UPDATE classes SET name = $3 WHERE classes.org_id = $1 AND classes.id = $2 AND classes.archived_at IS NULL
RETURNING classes.id, classes.org_id, classes.academic_year_id, classes.name, classes.created_by, classes.created_at, classes.archived_at, (SELECT count(*) FROM class_enrollments e WHERE e.class_id = classes.id AND e.ended_at IS NULL)::integer AS students
`

type RenameClassParams struct {
	OrgID uuid.UUID
	ID    uuid.UUID
	Name  string
}

type RenameClassRow struct {
	ID             uuid.UUID
	OrgID          uuid.UUID
	AcademicYearID uuid.UUID
	Name           string
	CreatedBy      uuid.UUID
	CreatedAt      pgtype.Timestamptz
	ArchivedAt     pgtype.Timestamptz
	Students       int32
}

func (q *Queries) RenameClass(ctx context.Context, arg RenameClassParams) (RenameClassRow, error) {
	row := q.db.QueryRow(ctx, renameClass, arg.OrgID, arg.ID, arg.Name)
	var i RenameClassRow
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.AcademicYearID,
		&i.Name,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.ArchivedAt,
		&i.Students,
	)
	return i, err
}

const setActiveYear = `-- name: SetActiveYear :execrows
UPDATE academic_years SET active = true WHERE org_id = $1 AND id = $2
`

type SetActiveYearParams struct {
	OrgID uuid.UUID
	ID    uuid.UUID
}

func (q *Queries) SetActiveYear(ctx context.Context, arg SetActiveYearParams) (int64, error) {
	result, err := q.db.Exec(ctx, setActiveYear, arg.OrgID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
